-- Design blueprint. Migrations are introduced in M3/M7; not an active M1 DB.
PRAGMA foreign_keys=ON;
CREATE TABLE zalo_source(id TEXT PRIMARY KEY, account_reference TEXT NOT NULL);
CREATE TABLE conversation(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES zalo_source(id), external_id TEXT NOT NULL, title TEXT NOT NULL, allowed INTEGER NOT NULL DEFAULT 0 CHECK(allowed IN(0,1)), UNIQUE(source_id,external_id));
CREATE TABLE message(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversation(id), external_id TEXT, fingerprint TEXT NOT NULL, message_timestamp TEXT, timestamp_original TEXT, sender TEXT, raw_text TEXT NOT NULL, raw_metadata TEXT NOT NULL, captured_at TEXT NOT NULL, UNIQUE(conversation_id,external_id));
CREATE INDEX message_fingerprint ON message(conversation_id,fingerprint);
CREATE TABLE file_record(id TEXT PRIMARY KEY, sha256 TEXT NOT NULL UNIQUE CHECK(length(sha256)=64), size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), media_type TEXT, archive_relative_path TEXT, retention_state TEXT NOT NULL);
CREATE TABLE attachment(id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES message(id), external_identity TEXT, fingerprint TEXT NOT NULL, original_name TEXT, kind TEXT NOT NULL, file_id TEXT REFERENCES file_record(id), state TEXT NOT NULL, UNIQUE(message_id,external_identity));
CREATE TABLE delivery_bundle(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversation(id), created_at TEXT NOT NULL);
CREATE TABLE bundle_revision(id TEXT PRIMARY KEY, bundle_id TEXT NOT NULL REFERENCES delivery_bundle(id), revision INTEGER NOT NULL CHECK(revision>0), fingerprint TEXT NOT NULL, confidence REAL CHECK(confidence BETWEEN 0 AND 1), ruleset_version TEXT NOT NULL, state TEXT NOT NULL, UNIQUE(bundle_id,revision), UNIQUE(bundle_id,fingerprint));
CREATE TABLE bundle_message(revision_id TEXT NOT NULL REFERENCES bundle_revision(id), message_id TEXT NOT NULL REFERENCES message(id), reason TEXT NOT NULL, PRIMARY KEY(revision_id,message_id));
CREATE TABLE bundle_attachment(revision_id TEXT NOT NULL REFERENCES bundle_revision(id), attachment_id TEXT NOT NULL REFERENCES attachment(id), reason TEXT NOT NULL, PRIMARY KEY(revision_id,attachment_id));
CREATE TABLE document(id TEXT PRIMARY KEY, attachment_id TEXT NOT NULL REFERENCES attachment(id), file_id TEXT NOT NULL REFERENCES file_record(id), role TEXT, document_number TEXT, document_date TEXT, delivery_note_date TEXT, weighing_note_date TEXT);
CREATE TABLE document_page(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES document(id), page_number INTEGER NOT NULL CHECK(page_number>0), text_content TEXT, UNIQUE(document_id,page_number));
CREATE TABLE extraction(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES bundle_revision(id), field_name TEXT NOT NULL, value_original TEXT, value_normalized TEXT, unit TEXT, confidence REAL CHECK(confidence BETWEEN 0 AND 1), method TEXT NOT NULL, layer TEXT NOT NULL CHECK(layer IN('RAW','EXTRACTED','VERIFIED')));
CREATE TABLE extraction_evidence(id TEXT PRIMARY KEY, extraction_id TEXT NOT NULL REFERENCES extraction(id), page_id TEXT REFERENCES document_page(id), message_id TEXT REFERENCES message(id), source_location TEXT, CHECK((page_id IS NOT NULL)+(message_id IS NOT NULL)=1));
CREATE TABLE material(id TEXT PRIMARY KEY, normalized_name TEXT NOT NULL UNIQUE, code TEXT UNIQUE);
CREATE TABLE project(id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE);
CREATE TABLE supplier(id TEXT PRIMARY KEY, normalized_name TEXT NOT NULL);
CREATE TABLE delivery(id TEXT PRIMARY KEY, bundle_id TEXT NOT NULL REFERENCES delivery_bundle(id), revision_id TEXT NOT NULL UNIQUE REFERENCES bundle_revision(id), project_id TEXT REFERENCES project(id), supplier_id TEXT REFERENCES supplier(id), confirmed_delivery_date TEXT, chat_stated_date TEXT, document_number TEXT, validation_status TEXT NOT NULL, accounting_active INTEGER NOT NULL DEFAULT 0 CHECK(accounting_active IN(0,1)), pdf_file_id TEXT REFERENCES file_record(id), location TEXT, vehicle_number TEXT, delivered_by TEXT, received_by TEXT, weighing_note_number TEXT, notes TEXT);
CREATE UNIQUE INDEX one_active_delivery_per_bundle ON delivery(bundle_id) WHERE accounting_active=1;
CREATE TABLE delivery_line(id TEXT PRIMARY KEY, delivery_id TEXT NOT NULL REFERENCES delivery(id), material_id TEXT REFERENCES material(id), specification TEXT, unit TEXT NOT NULL, requested_quantity TEXT, ordered_quantity TEXT, delivered_quantity TEXT, received_quantity TEXT, accepted_quantity TEXT, returned_quantity TEXT, weight TEXT, requested_evidence_id TEXT REFERENCES extraction(id), ordered_evidence_id TEXT REFERENCES extraction(id), delivered_evidence_id TEXT REFERENCES extraction(id), received_evidence_id TEXT REFERENCES extraction(id), accepted_evidence_id TEXT REFERENCES extraction(id), returned_evidence_id TEXT REFERENCES extraction(id), weight_evidence_id TEXT REFERENCES extraction(id));
CREATE TABLE validation_issue(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES bundle_revision(id), code TEXT NOT NULL, severity TEXT NOT NULL, detail TEXT NOT NULL, evidence_ids TEXT NOT NULL, resolved_at TEXT, reviewer TEXT, resolution TEXT);
CREATE TABLE checkpoint(conversation_id TEXT PRIMARY KEY REFERENCES conversation(id), scanned_cursor TEXT, finalized_cursor TEXT, last_processed_message_id TEXT REFERENCES message(id), last_scan_time TEXT, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE processed_message(message_id TEXT PRIMARY KEY REFERENCES message(id), revision_id TEXT REFERENCES bundle_revision(id), terminal_reason TEXT NOT NULL);
CREATE TABLE processed_attachment(attachment_id TEXT PRIMARY KEY REFERENCES attachment(id), revision_id TEXT NOT NULL REFERENCES bundle_revision(id));
CREATE TABLE processed_bundle(revision_id TEXT PRIMARY KEY REFERENCES bundle_revision(id), committed_at TEXT NOT NULL);
CREATE TABLE agent_run(id TEXT PRIMARY KEY, started_at TEXT NOT NULL, ended_at TEXT, counters_json TEXT NOT NULL);
CREATE TABLE agent_job(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES agent_run(id), revision_id TEXT REFERENCES bundle_revision(id), state TEXT NOT NULL, state_version INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, next_retry_at TEXT, lease_owner TEXT, lease_expires_at TEXT, cache_relative_path TEXT, error_code TEXT);
CREATE TABLE agent_log(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES agent_run(id), job_id TEXT REFERENCES agent_job(id), occurred_at TEXT NOT NULL, event TEXT NOT NULL, safe_metadata_json TEXT NOT NULL);
CREATE TABLE ai_request_log(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES agent_job(id), model_alias TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL, tokens INTEGER, error_code TEXT);
CREATE TABLE publication_outbox(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES bundle_revision(id), file_id TEXT NOT NULL REFERENCES file_record(id), storage_root_alias TEXT NOT NULL, relative_path TEXT NOT NULL, state TEXT NOT NULL, UNIQUE(storage_root_alias,relative_path));
CREATE TABLE review_audit(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES bundle_revision(id), actor TEXT NOT NULL, occurred_at TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL);
-- Application invariant: verified values require evidence; all quantity strings validated
-- by Decimal parsing before commit. Cross-table invariants require transactional services.
-- Signed URLs/session credentials are never persisted in these business tables.
